#include <bits/stdc++.h>
using namespace std;const int N=512,P=998244353,G=3;static int a[N],b[N],c[N],d[N],e[N],h[N],r[N],o[N];int pw(int a,int b=P-2){int s=1;for(;b;b>>=1,a=1LL*a*a%P)if(b&1)s=1LL*s*a%P;return s;}void f(int*a,int n,int q){for(int i=0;i<n;i++)if(i<r[i])swap(a[i],a[r[i]]);for(int l=2;l<=n;l<<=1){int w=pw(G,(P-1)/l);if(q<0)w=pw(w);for(int i=0;i<n;i+=l)for(int j=0,s=1;j<l/2;j++,s=1LL*s*w%P){int x=a[i+j],y=1LL*s*a[i+j+l/2]%P;a[i+j]=(x+y)%P;a[i+j+l/2]=(x-y+P)%P;}}if(q<0){int w=pw(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*w%P;}}void iv(const int*x,int n,int*y){memset(y,0,n*sizeof(int));y[0]=pw(x[0]);for(int k=1;k<n;k<<=1){int l=min(k<<1,n),q=1,s=0;while(q<l*2)q<<=1,s++;memset(e,0,q*sizeof(int));memset(h,0,q*sizeof(int));memcpy(e,x,l*sizeof(int));memcpy(h,y,k*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(e,q,1);f(h,q,1);for(int i=0;i<q;i++)h[i]=1LL*h[i]*(2-1LL*e[i]*h[i]%P+P)%P;f(h,q,-1);memcpy(y+k,h+k,(l-k)*sizeof(int));}}void cv(const int*x,int n,const int*y,int m,int*o,int z){int q=1,s=0;while(q<n+m-1)q<<=1,s++;memset(e,0,q*sizeof(int));memset(h,0,q*sizeof(int));memcpy(e,x,n*sizeof(int));memcpy(h,y,m*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(e,q,1);f(h,q,1);for(int i=0;i<q;i++)e[i]=1LL*e[i]*h[i]%P;f(e,q,-1);memcpy(o,e,z*sizeof(int));}int main(int C,char**V){ios::sync_with_stdio(0);cin.tie(0);int R=C>1?stoi(V[1]):1000;unsigned long long s=C>2?stoull(V[2]):1;mt19937_64 g(s);while(R--){int n=g()%100+1;a[0]=1;for(int i=1;i<n;i++)a[i]=g()%P;memset(b,0,n*sizeof(int));b[0]=1;for(int k=1;k<n;k<<=1){int l=min(k<<1,n);iv(b,l,c);cv(a,l,c,l,d,l);for(int i=0;i<l;i++)b[i]=1LL*(b[i]+d[i])*(P+1)/2%P;}o[0]=1;for(int i=1;i<n;i++){long long q=0;for(int j=1;j<i;j++)q=(q+1LL*o[j]*o[i-j])%P;o[i]=1LL*(a[i]-q+P)*(P+1)/2%P;}for(int i=0;i<n;i++)if(b[i]!=o[i])return cout<<"WA\n",1;}cout<<"OK\n";}
